function weatherRenderer(params){
  var v = params.value;
  var active = String(v).toLowerCase() === 'active';
  var color = active ? 'var(--appsmith-theme-successColor, #34d399)' : 'var(--appsmith-theme-textSecondaryColor, #94a3b8)';
  return '<span style="display:inline-flex;align-items:center;gap:8px;">'
    + '<span style="width:9px;height:9px;border-radius:50%;background:' + color + ';display:inline-block;"></span>'
    + (v == null ? '' : v) + '</span>';
}

var COLS = [
  { headerName: 'Description', field: 'Description', flex: 1.3, minWidth: 140 },
  { headerName: 'Type', field: 'Type', flex: 1.1, minWidth: 120 },
  { headerName: 'Service Address', field: 'Service Address', flex: 1.3, minWidth: 150 },
  { headerName: 'City', field: 'City', flex: 1, minWidth: 100 },
  { headerName: 'State', field: 'State', width: 90, minWidth: 80 },
  { headerName: 'Zip', field: 'Zip', width: 110, minWidth: 90 },
  { headerName: 'Area (Sq. Ft)', field: 'Area (Sq. Ft)', width: 130, minWidth: 110, type: 'numericColumn' },
  { headerName: 'Weather', field: 'Weather', width: 130, minWidth: 110, cellRenderer: weatherRenderer }
];

var gridApi = null;
var lastSig = '';

function getRows(model){ return (model && Array.isArray(model.data)) ? model.data : []; }

function dataSig(model){
  var r = getRows(model);
  var first = r[0] && r[0].id;
  var last = r[r.length - 1] && r[r.length - 1].id;
  return (model && model.isLoading ? 'L' : '') + r.length + ':' + first + ':' + last;
}

function onCellClicked(e){
  var row = e.data;
  if (!row) return;
  appsmith.updateModel({ clickedRowData: row });
  appsmith.triggerEvent('onRowClick');
}

function render(model){
  var gridDiv = document.querySelector('#myGrid');
  if (!gridDiv) return;
  gridDiv.innerHTML = '';
  gridApi = agGrid.createGrid(gridDiv, {
    columnDefs: COLS,
    rowData: getRows(model),
    domLayout: 'autoHeight',
    pagination: true,
    paginationPageSize: 20,
    paginationPageSizeSelector: [10, 20, 30, 40, 50, 100],
    animateRows: true,
    defaultColDef: { resizable: true, sortable: true, minWidth: 90 },
    popupParent: document.body,
    getRowId: function(p){ return String(p.data.id); },
    overlayNoRowsTemplate: '<span style="color:var(--appsmith-theme-textSecondaryColor, #94a3b8);font-style:italic;">No locations found</span>',
    onGridReady: function(p){ gridApi = p.api; },
    onCellClicked: onCellClicked
  });
  lastSig = dataSig(model);
}

appsmith.onReady(function(){
  render(appsmith.model);
  appsmith.onModelChange(function(model){
    if (!gridApi){ render(model); return; }
    var sig = dataSig(model);
    if (sig !== lastSig){
      lastSig = sig;
      gridApi.setGridOption('rowData', getRows(model));
    }
  });
});

